using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize(Roles="Admin,SuperAdmin")] public class AdminController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger):Controller {
 public async Task<IActionResult> Index(){ViewBag.Pending=await db.HostApplications.CountAsync(a=>a.Status=="Pending");ViewBag.Bookings=await db.Bookings.CountAsync();ViewBag.Users=await users.Users.CountAsync();return View();}
 public async Task<IActionResult> Applications(){return View(await db.HostApplications.Include(a=>a.Applicant).Include(a=>a.Property).Include(a=>a.Property!.Images).Where(a=>a.Status=="Pending").OrderBy(a=>a.SubmittedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Review(int id,string decision,string? notes){if(decision is not("Approved" or "Rejected"))return BadRequest();var app=await db.HostApplications.Include(a=>a.Property).FirstOrDefaultAsync(a=>a.Id==id);if(app==null)return NotFound();if(app.Status!="Pending")return BadRequest("Application already reviewed.");var applicant=await users.FindByIdAsync(app.ApplicantId);if(applicant==null)return NotFound();app.Status=decision;app.AdminNotes=notes;app.ReviewedAt=DateTime.UtcNow;app.ReviewedById=users.GetUserId(User);if(decision=="Approved"){await users.RemoveFromRoleAsync(applicant,"Guest");if(!await users.IsInRoleAsync(applicant,"Host"))await users.AddToRoleAsync(applicant,"Host");if(app.Property!=null)app.Property.IsActive=true;}db.Notifications.Add(new Notification{UserId=app.ApplicantId,Title="Host application "+decision,Body=decision=="Approved"?"Your application was approved. You can now manage your property as a Host.":"Your application was rejected. Check the admin notes or contact support.",Link="/HostApplications/MyApplications"});await db.SaveChangesAsync();await logger.LogAsync(users.GetUserId(User),"HostApplicationReviewed",$"Application #{id} {decision}; Guest-to-Host role transition applied when approved.","HostApplication",id.ToString());return RedirectToAction(nameof(Applications));}
 [Authorize(Roles="SuperAdmin")] public async Task<IActionResult> Users(){var list=await users.Users.OrderBy(u=>u.Email).ToListAsync();ViewBag.RoleMap=list.ToDictionary(u=>u.Id,u=>string.Join(", ",users.GetRolesAsync(u).GetAwaiter().GetResult()));return View(list);}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="SuperAdmin")] public async Task<IActionResult> Promote(string userId){var target=await users.FindByIdAsync(userId);if(target==null)return NotFound();if(await users.IsInRoleAsync(target,"SuperAdmin"))return BadRequest("SuperAdmin role cannot be changed here.");if(await users.IsInRoleAsync(target,"Host"))return BadRequest("Hosts cannot be promoted using the Guest promotion workflow.");await users.RemoveFromRoleAsync(target,"Guest");if(!await users.IsInRoleAsync(target,"Admin"))await users.AddToRoleAsync(target,"Admin");await logger.LogAsync(users.GetUserId(User),"RoleChanged",$"Promoted user {target.Email} to Admin.","User",userId);await db.SaveChangesAsync();return RedirectToAction(nameof(Users));}
 public async Task<IActionResult> Logs(){return View(await db.ActivityLogs.OrderByDescending(l=>l.CreatedAt).Take(500).ToListAsync());}
 public async Task<IActionResult> ViewDocumentFile(int id){var d=await db.GuestDocuments.FirstOrDefaultAsync(x=>x.Id==id);if(d==null)return NotFound();var path=Path.Combine(Directory.GetCurrentDirectory(),"PrivateUploads",d.FilePath);if(!System.IO.File.Exists(path))return NotFound();var ext=Path.GetExtension(path).ToLowerInvariant();var contentType=ext==".pdf"?"application/pdf":ext==".png"?"image/png":"image/jpeg";return PhysicalFile(path,contentType,enableRangeProcessing:true);}
 public async Task<IActionResult> Documents(){var docs=await db.GuestDocuments.Include(d=>d.Booking).ThenInclude(b=>b!.Property).Include(d=>d.Booking).ThenInclude(b=>b!.Guest).OrderByDescending(d=>d.UploadedAt).ToListAsync();return View(docs);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> VerifyDocument(int id,string decision){if(decision is not("Verified" or "Rejected"))return BadRequest();var d=await db.GuestDocuments.Include(x=>x.Booking).FirstOrDefaultAsync(x=>x.Id==id);if(d==null)return NotFound();if(d.Booking?.Property?.HostId!=users.GetUserId(User)&&!User.IsInRole("Admin")&&!User.IsInRole("SuperAdmin"))return Forbid();d.Status=decision;d.ReviewedAt=DateTime.UtcNow;await db.SaveChangesAsync();await logger.LogAsync(users.GetUserId(User),"DocumentReviewed",$"Document #{id} marked {decision}.","GuestDocument",id.ToString());return RedirectToAction(nameof(Documents));}
}